"""Versioned, curated question bank. No dynamic exercise tests are generated by AI."""

from dataclasses import dataclass
from typing import Literal

QUESTION_BANK_VERSION = "2026-11-v1"
AnswerKind = Literal["single_choice", "integer_or_unknown"]


@dataclass(frozen=True)
class Option:
    id: str
    label: str


@dataclass(frozen=True)
class Question:
    id: str
    module: str
    prompt: str
    kind: AnswerKind
    options: tuple[Option, ...] = ()
    minimum: int | None = None
    maximum: int | None = None
    hint: str | None = None
    version: int = 1


def choice(id: str, module: str, prompt: str, options: tuple[Option, ...],
           hint: str | None = None) -> Question:
    return Question(id=id, module=module, prompt=prompt,
                    kind="single_choice", options=options, hint=hint)


def number(id: str, module: str, prompt: str, maximum: int,
           hint: str | None = None) -> Question:
    return Question(id=id, module=module, prompt=prompt,
                    kind="integer_or_unknown", minimum=0, maximum=maximum,
                    hint=hint)


